HTML_CONTENT = '<!DOCTYPE html>\n<html lang="es-AR">\n<head>\n<meta charset="UTF-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />\n<title>DS Compras</title>\n<link rel="icon" href="data:image/png;base64," />\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --paper: #FFFDF8;\n    --paper-dark: #FDF3DE;\n    --ink: #16202B;\n    --ink-soft: #6B7480;\n    --navy: #1B3A5C;\n    --navy-deep: #102844;\n    --gold: #C79A44;\n    --gold-soft: #F4DFA6;\n    --coral: #FF6F5E;\n    --coral-soft: #FFE1DC;\n    --mint: #22B893;\n    --mint-soft: #DCF5EC;\n    --verified: #22B893;\n    --verified-bg: #DCF5EC;\n    --warning: #C7860A;\n    --warning-bg: #FBEACB;\n    --danger: #E0574A;\n    --accent: var(--navy);\n    --line: #EAD9AE;\n    --radius: 18px;\n    --radius-sm: 10px;\n  }\n\n  * { box-sizing: border-box; }\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    color: var(--ink);\n    font-family: \'Fredoka\', sans-serif;\n    font-weight: 400;\n    -webkit-font-smoothing: antialiased;\n  }\n\n  body {\n    min-height: 100vh;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    background:\n      radial-gradient(circle at 15% 0%, #FFF6E0 0%, transparent 45%),\n      radial-gradient(circle at 85% 15%, #FDE7DE 0%, transparent 40%),\n      linear-gradient(180deg, #FFFDF8 0%, var(--paper-dark) 100%);\n    background-attachment: fixed;\n  }\n\n  header {\n    width: 100%;\n    max-width: 480px;\n    padding: 22px 16px 8px;\n    text-align: center;\n  }\n\n  header img.logo {\n    width: 232px;\n    height: auto;\n    display: block;\n    margin: 0 auto 6px;\n    filter: drop-shadow(0 6px 10px rgba(16, 40, 68, 0.25));\n    animation: float 3.4s ease-in-out infinite;\n  }\n\n  @keyframes float {\n    0%, 100% { transform: translateY(0) rotate(-1deg); }\n    50% { transform: translateY(-6px) rotate(1deg); }\n  }\n\n  header .brand {\n    font-family: \'Fredoka\', sans-serif;\n    font-weight: 700;\n    font-size: 20px;\n    letter-spacing: 0.02em;\n    color: var(--navy-deep);\n  }\n\n  header .brand span { color: var(--gold); }\n\n  header .sub {\n    margin-top: 2px;\n    font-size: 12px;\n    color: var(--ink-soft);\n    font-family: \'Fredoka\', sans-serif;\n    font-weight: 500;\n  }\n\n  #feed {\n    width: 100%;\n    max-width: 480px;\n    flex: 1;\n    overflow-y: auto;\n    padding: 4px 12px 150px;\n    display: flex;\n    flex-direction: column;\n    gap: 14px;\n  }\n\n  .msg-user {\n    align-self: flex-end;\n    max-width: 82%;\n    background: linear-gradient(135deg, var(--navy) 0%, var(--navy-deep) 100%);\n    color: #FFF8E8;\n    padding: 11px 16px;\n    border-radius: 18px 18px 4px 18px;\n    font-size: 14.5px;\n    line-height: 1.4;\n    box-shadow: 0 4px 10px rgba(16, 40, 68, 0.18);\n    animation: pop-in 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);\n  }\n\n  .msg-agent-text {\n    align-self: flex-start;\n    max-width: 90%;\n    font-size: 14.5px;\n    line-height: 1.5;\n    padding: 4px 6px;\n    white-space: pre-line;\n    animation: pop-in 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);\n  }\n\n  .buy-wait {\n    align-self: stretch;\n    background: var(--verified-bg);\n    border-left: 4px solid var(--verified);\n    border-radius: var(--radius-sm);\n    padding: 12px 14px;\n    font-size: 13.5px;\n    line-height: 1.45;\n    animation: pop-in 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);\n  }\n  .buy-wait.esperar { background: var(--warning-bg); border-left-color: var(--warning); }\n  .buy-wait.neutro { background: #F0EEE6; border-left-color: var(--ink-soft); }\n\n  @keyframes pop-in {\n    from { opacity: 0; transform: translateY(10px) scale(0.98); }\n    to { opacity: 1; transform: none; }\n  }\n\n  #composer {\n    position: fixed;\n    bottom: 0;\n    left: 0; right: 0;\n    display: flex;\n    justify-content: center;\n    background: linear-gradient(to top, var(--paper-dark) 55%, transparent);\n    padding: 16px 12px calc(16px + env(safe-area-inset-bottom));\n  }\n\n  #composer form {\n    width: 100%;\n    max-width: 480px;\n    display: flex;\n    gap: 8px;\n  }\n\n  #composer input {\n    flex: 1;\n    border: 2px solid var(--navy-deep);\n    border-radius: 999px;\n    padding: 12px 18px;\n    font-size: 15px;\n    font-family: \'Fredoka\', sans-serif;\n    background: var(--paper);\n    color: var(--ink);\n  }\n  #composer input:focus { outline: 3px solid var(--gold-soft); outline-offset: 1px; }\n\n  #composer button {\n    border: none;\n    background: linear-gradient(135deg, var(--navy) 0%, var(--navy-deep) 100%);\n    color: var(--gold-soft);\n    padding: 0 22px;\n    border-radius: 999px;\n    font-family: \'Fredoka\', sans-serif;\n    font-weight: 600;\n    font-size: 14px;\n    cursor: pointer;\n    box-shadow: 0 4px 10px rgba(16, 40, 68, 0.25);\n    transition: transform 0.12s ease;\n  }\n  #composer button:active { transform: scale(0.94); }\n  #composer button:disabled { opacity: 0.5; }\n\n  .typing {\n    display: flex;\n    align-items: center;\n    gap: 4px;\n    padding: 6px 4px;\n  }\n  .typing .dot {\n    width: 7px;\n    height: 7px;\n    border-radius: 50%;\n    background: var(--gold);\n    animation: bounce-dot 1.1s ease-in-out infinite;\n  }\n  .typing .dot:nth-child(2) { animation-delay: 0.15s; }\n  .typing .dot:nth-child(3) { animation-delay: 0.3s; }\n  @keyframes bounce-dot {\n    0%, 60%, 100% { transform: translateY(0); opacity: 0.5; }\n    30% { transform: translateY(-6px); opacity: 1; }\n  }\n\n  .debug-line {\n    align-self: flex-start;\n    font-family: \'IBM Plex Mono\', monospace;\n    font-size: 10.5px;\n    color: var(--ink-soft);\n    background: var(--paper);\n    border: 1px dashed var(--line);\n    border-radius: var(--radius-sm);\n    padding: 5px 10px;\n    max-width: 90%;\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    * { animation-duration: 0.001s !important; animation-iteration-count: 1 !important; }\n  }\n\n  /* --- Splash de apertura --- */\n  #splash {\n    position: fixed;\n    inset: 0;\n    z-index: 999;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background:\n      radial-gradient(circle at 50% 30%, #1E4570 0%, var(--navy-deep) 70%);\n    transition: opacity 0.6s ease, visibility 0.6s;\n  }\n  #splash.hide { opacity: 0; visibility: hidden; pointer-events: none; }\n  .splash-frame {\n    width: min(62vw, 300px);\n    aspect-ratio: 4 / 5;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    animation: splash-pop 0.55s cubic-bezier(0.34, 1.56, 0.64, 1);\n  }\n  .splash-frame img {\n    width: 100%;\n    height: auto;\n    object-fit: contain;\n    filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.35));\n  }\n  @keyframes splash-pop {\n    from { opacity: 0; transform: scale(0.75); }\n    to { opacity: 1; transform: none; }\n  }\n\n  /* --- Grilla de productos: 2 columnas, estilo tienda --- */\n  .cards-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 10px;\n    width: 100%;\n  }\n\n  .ptile {\n    background: var(--paper);\n    border-radius: 16px;\n    padding: 10px;\n    display: flex;\n    flex-direction: column;\n    position: relative;\n    box-shadow: 0 6px 16px rgba(16, 40, 68, 0.10), 0 1px 4px rgba(16, 40, 68, 0.06);\n    animation: pop-in 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) backwards;\n  }\n\n  .ptile-badge {\n    position: absolute;\n    top: 8px;\n    left: 8px;\n    background: linear-gradient(135deg, var(--gold-soft) 0%, var(--gold) 130%);\n    color: #5C4419;\n    font-family: \'Fredoka\', sans-serif;\n    font-weight: 600;\n    font-size: 9px;\n    letter-spacing: 0.02em;\n    text-transform: uppercase;\n    padding: 3px 8px;\n    border-radius: 999px;\n    box-shadow: 0 2px 5px rgba(199, 154, 68, 0.4);\n    z-index: 1;\n  }\n\n  .ptile-img {\n    width: 100%;\n    aspect-ratio: 1 / 1;\n    object-fit: contain;\n    background: #fff;\n    border-radius: 12px;\n    margin-bottom: 8px;\n  }\n  .ptile-img.placeholder {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--line);\n    font-size: 28px;\n  }\n\n  .ptile-rank {\n    font-family: \'IBM Plex Mono\', monospace;\n    font-size: 9.5px;\n    color: var(--ink-soft);\n    margin-bottom: 2px;\n  }\n\n  .ptile-modelo {\n    font-size: 12px;\n    font-weight: 600;\n    line-height: 1.28;\n    color: var(--ink);\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n    min-height: 2.6em;\n  }\n\n  .ptile-seller {\n    font-size: 9.5px;\n    color: var(--ink-soft);\n    font-family: \'IBM Plex Mono\', monospace;\n    margin-top: 3px;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .ptile-price-old {\n    font-size: 10px;\n    text-decoration: line-through;\n    color: var(--ink-soft);\n    margin-top: 6px;\n  }\n\n  .ptile-price-now {\n    font-size: 16px;\n    font-weight: 700;\n    color: var(--navy-deep);\n    font-family: \'IBM Plex Mono\', monospace;\n    line-height: 1.2;\n  }\n\n  .ptile-info {\n    font-size: 10px;\n    color: var(--ink-soft);\n    margin-top: 4px;\n    line-height: 1.35;\n  }\n\n  .ptile-chip {\n    display: inline-block;\n    font-size: 9px;\n    font-family: \'Fredoka\', sans-serif;\n    font-weight: 500;\n    padding: 2px 7px;\n    border-radius: 999px;\n    margin-top: 5px;\n    margin-right: 3px;\n  }\n  .ptile-chip.promo { background: var(--mint-soft); color: #17694F; }\n  .ptile-chip.warn { background: var(--warning-bg); color: var(--warning); }\n  .ptile-chip.tie { background: var(--gold-soft); color: #5C4419; }\n\n  .ptile-link {\n    display: block;\n    text-align: center;\n    margin-top: 8px;\n    padding: 7px;\n    background: linear-gradient(135deg, var(--coral) 0%, #FF8A6E 100%);\n    color: #fff;\n    text-decoration: none;\n    font-family: \'Fredoka\', sans-serif;\n    font-size: 11px;\n    font-weight: 600;\n    border-radius: 999px;\n    box-shadow: 0 3px 8px rgba(255, 111, 94, 0.35);\n    transition: transform 0.12s ease;\n  }\n  .ptile-link:active { transform: scale(0.94); }\n\n  /* --- Grilla de bienvenida: onda "categorías de tienda", solo decorativa\n     y como atajo - al tocar, dispara una búsqueda por el chat (no hay\n     navegación ni links directos, el buscador sigue siendo el único\n     mecanismo real). --- */\n  .welcome-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 10px;\n    width: 100%;\n    margin-top: 4px;\n  }\n\n  .wtile {\n    background: var(--paper);\n    border: none;\n    border-radius: 16px;\n    padding: 14px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 6px;\n    font-family: \'Fredoka\', sans-serif;\n    box-shadow: 0 6px 14px rgba(16, 40, 68, 0.09);\n    animation: pop-in 0.32s cubic-bezier(0.34, 1.56, 0.64, 1) backwards;\n    transition: transform 0.12s ease;\n    cursor: pointer;\n  }\n  .wtile:active { transform: scale(0.93); }\n  .wtile .emoji {\n    font-size: 26px;\n    line-height: 1;\n  }\n  .wtile .label {\n    font-size: 10.5px;\n    font-weight: 600;\n    color: var(--navy-deep);\n    text-align: center;\n    line-height: 1.2;\n  }\n\n  /* --- Cintas animadas de "productos" (íconos, no fotos - ver aclaración\n     en el chat) que se deslizan solas en la pantalla de bienvenida. --- */\n  .marquee-wrap {\n    width: 100%;\n    overflow: hidden;\n    mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent);\n    -webkit-mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent);\n  }\n\n  .marquee-row {\n    display: flex;\n    gap: 10px;\n    width: max-content;\n    animation: marquee-left 24s linear infinite;\n  }\n  .marquee-row.reverse { animation-name: marquee-right; animation-duration: 28s; }\n\n  @keyframes marquee-left {\n    from { transform: translateX(0); }\n    to { transform: translateX(-50%); }\n  }\n  @keyframes marquee-right {\n    from { transform: translateX(-50%); }\n    to { transform: translateX(0); }\n  }\n\n  .mchip {\n    flex: 0 0 auto;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    background: var(--paper);\n    border-radius: 999px;\n    padding: 8px 14px;\n    box-shadow: 0 4px 10px rgba(16, 40, 68, 0.08);\n    font-family: \'Fredoka\', sans-serif;\n    font-size: 12px;\n    font-weight: 600;\n    color: var(--navy-deep);\n    white-space: nowrap;\n  }\n  .mchip .e { font-size: 18px; }\n\n  @media (prefers-reduced-motion: reduce) {\n    .marquee-row { animation: none !important; }\n  }\n</style>\n</head>\n<body>\n  <div id="splash">\n    <div class="splash-frame">\n      <img src="data:image/png;base64," alt="DS Compras" />\n    </div>\n  </div>\n\n  <header>\n    <img class="logo" src="data:image/png;base64," alt="DS Compras" />\n    <div class="brand">DS <span>Compras</span></div>\n    <div class="sub">tu agente inteligente</div>\n  </header>\n\n  <div id="feed"></div>\n\n  <div id="composer">\n    <form id="form">\n      <input id="input" type="text" placeholder="Ej: busco un aire acondicionado" autocomplete="off" />\n      <button type="submit">Enviar</button>\n    </form>\n  </div>\n\n<script>\nconst feed = document.getElementById(\'feed\');\nconst form = document.getElementById(\'form\');\nconst input = document.getElementById(\'input\');\nconst sessionId = \'web-\' + Math.random().toString(36).slice(2);\n\nfunction addUserMessage(text) {\n  const el = document.createElement(\'div\');\n  el.className = \'msg-user\';\n  el.textContent = text;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction addAgentText(text) {\n  const el = document.createElement(\'div\');\n  el.className = \'msg-agent-text\';\n  el.textContent = text;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction escapeHtml(text) {\n  const div = document.createElement(\'div\');\n  div.textContent = text ?? \'\';\n  return div.innerHTML;\n}\n\nfunction buildOfferTile(card, index) {\n  const imgHtml = card.image_url\n    ? `<img src="${escapeHtml(card.image_url)}" alt="" class="ptile-img" loading="lazy" onerror="this.style.display=\'none\'" />`\n    : `<div class="ptile-img placeholder">🛍️</div>`;\n\n  const chips = [];\n  if (card.promocion_texto && !card.promocion_texto.startsWith(\'sin \')) {\n    chips.push(`<span class="ptile-chip promo">🏷 ${escapeHtml(card.promocion_texto)}</span>`);\n  }\n  if (card.envio_texto && card.envio_texto.includes(\'gratis\')) {\n    chips.push(\'<span class="ptile-chip promo">🚚 Envío gratis</span>\');\n  }\n  if (card.empatado) {\n    chips.push(\'<span class="ptile-chip tie">🤝 Empate</span>\');\n  }\n  if ((card.warnings || []).length) {\n    chips.push(`<span class="ptile-chip warn" title="${escapeHtml(card.warnings.join(\' | \'))}">⚠ dato sin confirmar</span>`);\n  }\n\n  const linkHtml = card.link\n    ? `<a class="ptile-link" href="${escapeHtml(card.link)}" target="_blank" rel="noopener noreferrer">Ver oferta →</a>`\n    : \'\';\n\n  return `\n    <div class="ptile" style="animation-delay:${index * 0.06}s">\n      ${card.label ? `<span class="ptile-badge">${escapeHtml(card.label)}</span>` : \'\'}\n      ${imgHtml}\n      <div class="ptile-rank">#${card.rank}</div>\n      <div class="ptile-modelo">${escapeHtml(card.modelo)}</div>\n      <div class="ptile-seller">${escapeHtml(card.seller)}${card.fuente ? \' · \' + escapeHtml(card.fuente) : \'\'}</div>\n      <div class="ptile-price-old">${escapeHtml(card.precio_publicado)}</div>\n      <div class="ptile-price-now">${escapeHtml(card.costo_efectivo)}</div>\n      <div class="ptile-info">${escapeHtml(card.cuotas_texto)}</div>\n      <div>${chips.join(\'\')}</div>\n      ${linkHtml}\n    </div>\n  `;\n}\n\nfunction addOfferGrid(cards) {\n  if (!cards || !cards.length) return;\n  const grid = document.createElement(\'div\');\n  grid.className = \'cards-grid\';\n  grid.innerHTML = cards.map((c, i) => buildOfferTile(c, i)).join(\'\');\n  feed.appendChild(grid);\n  feed.scrollTop = feed.scrollHeight;\n}\n\n// Categorías decorativas de bienvenida - NO son links ni navegación, solo\n// un atajo visual: tocar una dispara una búsqueda por el ÚNICO mecanismo\n// real que tenemos (el chat/buscador), igual que si el usuario la hubiera\n// escrito. Se sacan de pantalla apenas se manda el primer mensaje.\nconst WELCOME_CATEGORIES = [\n  { emoji: \'❄️\', label: \'Aire acondicionado\', phrase: \'busco un aire acondicionado\' },\n  { emoji: \'📱\', label: \'Celulares\', phrase: \'busco un celular\' },\n  { emoji: \'📺\', label: \'Televisores\', phrase: \'busco un televisor\' },\n  { emoji: \'💻\', label: \'Notebooks\', phrase: \'busco una notebook\' },\n  { emoji: \'🧊\', label: \'Heladeras\', phrase: \'busco una heladera\' },\n  { emoji: \'🌀\', label: \'Lavarropas\', phrase: \'busco un lavarropas\' },\n];\n\nfunction addWelcomeGrid() {\n  const grid = document.createElement(\'div\');\n  grid.className = \'welcome-grid\';\n  grid.id = \'welcome-grid\';\n  grid.innerHTML = WELCOME_CATEGORIES.map((c, i) => `\n    <button type="button" class="wtile" data-phrase="${escapeHtml(c.phrase)}" style="animation-delay:${i * 0.05}s">\n      <span class="emoji">${c.emoji}</span>\n      <span class="label">${c.label}</span>\n    </button>\n  `).join(\'\');\n  grid.addEventListener(\'click\', (e) => {\n    const btn = e.target.closest(\'.wtile\');\n    if (!btn) return;\n    sendMessage(btn.dataset.phrase);\n  });\n  feed.appendChild(grid);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction removeWelcomeGrid() {\n  const el = document.getElementById(\'welcome-grid\');\n  if (el) el.remove();\n}\n\n// Cintas animadas decorativas de la bienvenida. Fila 1: electro/tecnología.\n// Fila 2: muebles de casa/oficina. Cada una se duplica (concat consigo\n// misma) para poder loopear sin corte animando translateX hasta -50%.\nconst MARQUEE_ROW_1 = [\n  { e: \'🧊\', t: \'Heladeras\' }, { e: \'🌀\', t: \'Lavarropas\' }, { e: \'❄️\', t: \'Aires acondicionados\' },\n  { e: \'📱\', t: \'Celulares\' }, { e: \'💻\', t: \'Notebooks\' }, { e: \'📲\', t: \'Tablets\' }, { e: \'🖨️\', t: \'Impresoras\' },\n];\nconst MARQUEE_ROW_2 = [\n  { e: \'🛋️\', t: \'Sillón 3 cuerpos\' }, { e: \'🛋️\', t: \'Sillón 2 cuerpos\' }, { e: \'🛏️\', t: \'Sommiers\' },\n  { e: \'🖥️\', t: \'Escritorios\' }, { e: \'👞\', t: \'Zapateros\' }, { e: \'🛌\', t: \'Mesas de luz\' },\n];\n\nfunction buildMarqueeRow(items, extraClass) {\n  const doubled = items.concat(items);\n  const chips = doubled.map(i => `<span class="mchip"><span class="e">${i.e}</span>${escapeHtml(i.t)}</span>`).join(\'\');\n  return `<div class="marquee-row ${extraClass}">${chips}</div>`;\n}\n\nfunction addMarquee() {\n  const wrap = document.createElement(\'div\');\n  wrap.id = \'marquee\';\n  wrap.innerHTML = `\n    <div class="marquee-wrap">${buildMarqueeRow(MARQUEE_ROW_1, \'\')}</div>\n    <div class="marquee-wrap" style="margin-top:8px">${buildMarqueeRow(MARQUEE_ROW_2, \'reverse\')}</div>\n  `;\n  feed.appendChild(wrap);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction removeMarquee() {\n  const el = document.getElementById(\'marquee\');\n  if (el) el.remove();\n}\n\nfunction addBuyWait(text, recommendation) {\n  const el = document.createElement(\'div\');\n  const cls = recommendation && recommendation.includes(\'esperar\') ? \'esperar\'\n            : recommendation && recommendation.includes(\'neutro\') ? \'neutro\' : \'\';\n  el.className = \'buy-wait \' + cls;\n  el.textContent = text;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction addDebugLine(intent, entities, router, memoria) {\n  const el = document.createElement(\'div\');\n  el.className = \'debug-line\';\n  const ents = Object.entries(entities || {}).map(([k, v]) => `${k}=${v}`).join(\', \') || \'(ninguna)\';\n  const routerCorto = router === \'LLMIntentRouter\' ? \'IA (Claude)\' : \'reglas fijas\';\n  const memoriaCorta = memoria === \'PostgresMemoryStore\' ? \'Postgres (persiste)\' : \'en proceso (no persiste)\';\n  el.textContent = `🔧 buscador=${routerCorto} · memoria=${memoriaCorta} · intent=${intent} · entidades: ${ents}`;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nasync function sendMessage(message) {\n  removeWelcomeGrid();\n  removeMarquee();\n  addUserMessage(message);\n  input.value = \'\';\n  input.disabled = true;\n\n  const typing = document.createElement(\'div\');\n  typing.className = \'typing\';\n  typing.innerHTML = \'<span class="dot"></span><span class="dot"></span><span class="dot"></span>\';\n  feed.appendChild(typing);\n  feed.scrollTop = feed.scrollHeight;\n\n  try {\n    const res = await fetch(\'/v1/chat\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ message, user_id: \'demo-user\', session_id: sessionId }),\n    });\n    const data = await res.json();\n    typing.remove();\n\n    if (data.debug_intent) addDebugLine(data.debug_intent, data.debug_entities, data.debug_router, data.debug_memory);\n    if (data.message) addAgentText(data.message);\n    addOfferGrid(data.cards);\n    if (data.buy_wait_text) {\n      addBuyWait(data.buy_wait_text, data.buy_wait_text.toLowerCase());\n    }\n  } catch (err) {\n    typing.remove();\n    addAgentText(\'Hubo un error de conexión. Probá de nuevo en un momento.\');\n  } finally {\n    input.disabled = false;\n    input.focus();\n  }\n}\n\nform.addEventListener(\'submit\', (e) => {\n  e.preventDefault();\n  const value = input.value.trim();\n  if (value) sendMessage(value);\n});\n\naddAgentText(\'Hola, soy DS Compras, tu buscador inteligente. Contame que estás buscando? (ej: "busco un aire acondicionado")\');\naddMarquee();\naddWelcomeGrid();\n\nconst splash = document.getElementById(\'splash\');\nsetTimeout(() => splash.classList.add(\'hide\'), 1300);\nsetTimeout(() => splash.remove(), 2000);\n</script>\n</body>\n</html>\n'